// ================== AYARLAR ==================
// Şifre/token değiştiğinde SADECE bu bloğu güncelleyin.
const AYARLAR = {
  // Bitrix24 gelen webhook (inbound) adresi, sonunda / olacak.
  // Örn: https://xre.bitrix24.com.tr/rest/1/abcdef123456/
  // Gerekli izinler: crm, user (user_brief yeterli)
  BITRIX_WEBHOOK_URL: 'https://BURAYA-PORTAL.bitrix24.com.tr/rest/1/BURAYA_WEBHOOK_KODU/',

  // Bitrix giden webhook (ONCRMLEAD*) kullanıyorsanız application_token.
  // Otomasyon kuralı (robot) ile tetikliyorsanız boş bırakın.
  BITRIX_APP_TOKEN: '',

  // "PROJELER SMS GELEN" statüsü
  HEDEF_STATU: 'UC_BVSKUN',

  // "İlgilendiğiniz Proje" bilgisi otomatik olarak form kaydından okunur.
  // Bulunamazsa bu lead alanı denenir (örn. UF_CRM_1712345678); boşsa
  // etiketinde "proje" geçen lead alanı aranır.
  PROJE_ALANI: '',

  TELEGRAM_BOT_TOKEN: 'BURAYA_TELEGRAM_BOT_TOKEN',
  // Grup: https://web.telegram.org/k/#-5156472580
  // "chat not found" hatası alırsanız -1005156472580 deneyin (supergroup).
  TELEGRAM_CHAT_ID: '-5156472580',

  ERCCELL_URL: 'https://gateway.erccell.com.tr/corporatesms/sendsms/',
  ERCCELL_USERNAME: 'BURAYA_ERCCELL_KULLANICI_ADI',
  ERCCELL_PASSWORD: 'BURAYA_ERCCELL_SIFRE',
  ERCCELL_BASLIK: 'XRE',
  // true: 905XXXXXXXXX, false: 5XXXXXXXXX
  SMS_ULKE_KODU: true,
};
// ==============================================

const req = $input.first().json;
const body = req.body || {};
const query = req.query || {};

// Giden webhook token kontrolü (ayarlandıysa)
if (AYARLAR.BITRIX_APP_TOKEN) {
  const token = body?.auth?.application_token ?? body['auth[application_token]'];
  if (token !== AYARLAR.BITRIX_APP_TOKEN) return [];
}

// Lead ID'yi her olası formattan çek:
//  - Giden webhook (ONCRMLEADADD/UPDATE): data[FIELDS][ID]
//  - Otomasyon kuralı webhook'u: document_id[2] = "LEAD_123" veya ?lead_id={{ID}}
let leadId =
  body?.data?.FIELDS?.ID ?? body['data[FIELDS][ID]'] ??
  query.lead_id ?? query.id ?? body.lead_id ?? body.id;

if (!leadId) {
  const doc = body.document_id ?? query.document_id ?? body['document_id[2]'] ?? query['document_id[2]'];
  const ham = Array.isArray(doc) ? doc[2] : (doc && typeof doc === 'object' ? doc[2] : doc);
  const m = String(ham ?? '').match(/(\d+)\s*$/);
  if (m) leadId = m[1];
}

if (!leadId || !/^\d+$/.test(String(leadId).trim())) return [];

const webhook = AYARLAR.BITRIX_WEBHOOK_URL.replace(/\/?$/, '/');
return [{
  json: {
    ...AYARLAR,
    BITRIX_WEBHOOK_URL: webhook,
    BITRIX_PORTAL_URL: webhook.split('/').slice(0, 3).join('/'),
    lead_id: String(leadId).trim(),
    // Tek istekte: lead, bağlı kişi, sorumlu, CRM form kaydı, lead alan tanımları
    batch_cmd: {
      lead: 'crm.lead.get?id=' + String(leadId).trim(),
      kisi: 'crm.contact.get?id=$result[lead][CONTACT_ID]',
      sorumlu: 'user.get?ID=$result[lead][ASSIGNED_BY_ID]',
      form: 'crm.activity.list?filter[OWNER_TYPE_ID]=1&filter[OWNER_ID]=' + String(leadId).trim() +
        '&filter[PROVIDER_ID]=CRM_WEBFORM&order[ID]=DESC' +
        '&select[]=ID&select[]=SUBJECT&select[]=CREATED&select[]=DESCRIPTION&select[]=PROVIDER_PARAMS',
      alanlar: 'crm.lead.fields',
    },
  },
}];

const cfg = $('Ayarlar ve Lead ID').first().json;
const R = $input.first().json?.result?.result || {};
const lead = R.lead;

// Sadece "PROJELER SMS GELEN" statüsündeki lead'ler
if (!lead || lead.STATUS_ID !== cfg.HEDEF_STATU) return [];

// Aynı lead için ikinci kez SMS/bildirim gitmesin
const store = $getWorkflowStaticData('global');
store.islenenler = store.islenenler || {};
const simdi = Date.now();
for (const [id, t] of Object.entries(store.islenenler)) {
  if (simdi - t > 90 * 24 * 3600 * 1000) delete store.islenenler[id];
}
if (store.islenenler[lead.ID]) return [];
store.islenenler[lead.ID] = simdi;

const kisi = R.kisi && typeof R.kisi === 'object' && !Array.isArray(R.kisi) ? R.kisi : {};
const sorumluU = Array.isArray(R.sorumlu) ? R.sorumlu[0] : null;
const formKayit = Array.isArray(R.form) ? R.form[0] : null;
const alanTanim = R.alanlar || {};

const temizle = (s) => String(s ?? '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/\[\/?[a-z]+[^\]]*\]/gi, '')
  .replace(/&nbsp;/g, ' ')
  .trim();

const degerYaz = (v) => {
  if (v == null) return '';
  if (Array.isArray(v)) return v.map(degerYaz).filter(Boolean).join(', ');
  if (typeof v === 'object') return degerYaz(v.value ?? v.VALUE ?? v.text ?? v.TEXT ?? v.title ?? v.NAME ?? '');
  return temizle(v);
};

// ---- CRM form kaydındaki alanlar (İlk adı, Soyadı, Telefon, İlgilendiğiniz Proje ...) ----
let pp = formKayit?.PROVIDER_PARAMS;
if (typeof pp === 'string') { try { pp = JSON.parse(pp); } catch (e) { pp = null; } }
const formAlanlar = [];
for (const f of (pp?.FIELDS || pp?.fields || [])) {
  formAlanlar.push({
    caption: temizle(f.caption ?? f.CAPTION ?? f.label ?? f.LABEL ?? ''),
    name: String(f.name ?? f.NAME ?? ''),
    type: String(f.type ?? f.TYPE ?? ''),
    value: degerYaz(f.values ?? f.VALUES ?? f.value ?? f.VALUE),
  });
}
// Yedek: açıklama metnindeki "Başlık: değer" satırları
if (!formAlanlar.length && formKayit?.DESCRIPTION) {
  for (const satir of temizle(formKayit.DESCRIPTION).split('\n')) {
    const m = satir.match(/^\s*([^:]{2,60}):\s*(.+)$/);
    if (m) formAlanlar.push({ caption: m[1].trim(), name: '', type: '', value: m[2].trim() });
  }
}
const kucuk = (s) => String(s).toLocaleLowerCase('tr-TR');
const formBul = (capRe, nameRe, typeRe) => {
  const f = formAlanlar.find(a => a.value && (
    (capRe && capRe.test(kucuk(a.caption))) || (nameRe && nameRe.test(a.name)) || (typeRe && typeRe.test(a.type))));
  return f ? f.value : '';
};

const formAdSoyad = formBul(/ad\s*[-\/]?\s*soyad|full\s*name/i);
const formAd = formBul(/^(ilk\s*ad[ıi]?|ad[ıi]n[ıi]z|ad[ıi]?|isim|first\s*name|name)(?![a-zçğıöşü])/i, /^(LEAD_|CONTACT_)?NAME$/i);
const formSoyad = formBul(/soyad|last\s*name|surname/i, /LAST_NAME$/i);
const formTel = formBul(/telefon|phone|gsm|cep/i, /PHONE/i, /phone/i);
const formMail = formBul(/e-?posta|e-?mail/i, /EMAIL/i, /email/i);
const formProje = formBul(/proje/i);
const formCevap = formBul(/mesaj|cevap|not|a[cç][ıi]klama|soru|yorum/i);

const birlestir = (...p) => p.map(s => (s || '').trim()).filter(Boolean).join(' ');
const ilkCoklu = (arr) => (arr || []).map(p => p.VALUE).find(Boolean) || '';

const full_name =
  formAdSoyad || birlestir(formAd, formSoyad) ||
  birlestir(lead.NAME, lead.SECOND_NAME, lead.LAST_NAME) ||
  birlestir(kisi.NAME, kisi.SECOND_NAME, kisi.LAST_NAME) ||
  'Değerli Müşterimiz';

const hamTel = formTel || ilkCoklu(lead.PHONE) || ilkCoklu(kisi.PHONE);
let on = String(hamTel).replace(/\D/g, '');
if (on.startsWith('0090')) on = on.slice(4);
else if (on.startsWith('90') && on.length === 12) on = on.slice(2);
else if (on.startsWith('0') && on.length === 11) on = on.slice(1);
const telGecerli = /^5\d{9}$/.test(on);
const sms_phone = telGecerli ? (cfg.SMS_ULKE_KODU ? '90' + on : on) : '';
const phone = telGecerli ? '+90' + on : (hamTel || '-');

const email = formMail || ilkCoklu(lead.EMAIL) || ilkCoklu(kisi.EMAIL) || '-';

// ---- İlgilendiği proje ----
const alanDegeri = (kod) => {
  const v = lead[kod];
  if (v == null || v === '' || (Array.isArray(v) && !v.length)) return '';
  const items = alanTanim[kod]?.items;
  if (Array.isArray(items) && items.length) {
    const ids = (Array.isArray(v) ? v : [v]).map(String);
    return items.filter(i => ids.includes(String(i.ID))).map(i => i.VALUE).join(', ') || degerYaz(v);
  }
  return degerYaz(v);
};
let proje = formProje || (cfg.PROJE_ALANI ? alanDegeri(cfg.PROJE_ALANI) : '');
if (!proje) {
  for (const [kod, t] of Object.entries(alanTanim)) {
    const etiket = [t.title, t.listLabel, t.formLabel, t.filterLabel].join(' ');
    if (/proje/i.test(etiket) && (proje = alanDegeri(kod))) break;
  }
}

// ---- Form adı: "XRE PROJECT BİLGİ FORMU" ----
const tirnakIci = (s) => (String(s || '').match(/["“«]([^"”»]+)["”»]/) || [])[1] || '';
const form_adi =
  temizle(pp?.FORM?.NAME ?? pp?.form?.name ?? '') ||
  tirnakIci(formKayit?.SUBJECT) || tirnakIci(lead.TITLE) ||
  temizle(lead.SOURCE_DESCRIPTION) || temizle(lead.TITLE) || 'XRE Project Bilgi Formu';

const tarihKaynak = new Date(formKayit?.CREATED || lead.DATE_CREATE || Date.now());
const tarih = tarihKaynak.toLocaleString('tr-TR', {
  timeZone: 'Europe/Istanbul',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});

const sorumlu = sorumluU
  ? birlestir(sorumluU.NAME, sorumluU.LAST_NAME) || sorumluU.EMAIL || ('#' + lead.ASSIGNED_BY_ID)
  : (lead.ASSIGNED_BY_ID ? '#' + lead.ASSIGNED_BY_ID : '-');

return [{
  json: {
    lead_id: lead.ID,
    full_name,
    phone,
    sms_phone,
    email,
    form_adi,
    proje: proje || '-',
    cevap: formCevap || temizle(lead.COMMENTS) || '-',
    tarih,
    sorumlu,
    bitrix_link: cfg.BITRIX_PORTAL_URL + '/crm/lead/details/' + lead.ID + '/',
    // Kontrol için: form kaydından okunan alanlar ve Bitrix hataları
    form_alanlari: formAlanlar.map(a => a.caption + ': ' + a.value),
    bitrix_hatalar: $input.first().json?.result?.result_error || {},
  },
}];

const cfg = $('Ayarlar ve Lead ID').first().json;
const b = $input.first().json;

const sms_mesaj =
  'Merhaba ' + b.full_name + ', XRE Project başvurunuz alınmıştır. ' +
  'Proje satış temsilcimiz sizinle en kısa sürede iletişime geçecektir. ' +
  "XRE'li günler dileriz. https://xre.com.tr/";

const cdata = (s) => '<![CDATA[' + String(s).replace(/]]>/g, ']]]]><![CDATA[>') + ']]>';
const xmlEsc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const sms_xml =
`<?xml version="1.0" encoding="UTF-8"?>
<CORPORATESMS>
    <HEADER>
        <USERNAME>${xmlEsc(cfg.ERCCELL_USERNAME)}</USERNAME>
        <PASSWORD>${xmlEsc(cfg.ERCCELL_PASSWORD)}</PASSWORD>
        <SMSHEADER>${cdata(cfg.ERCCELL_BASLIK)}</SMSHEADER>
        <SMSTYPE>UC</SMSTYPE>
        <SENDTYPE>1:N</SENDTYPE>
    </HEADER>
    <SMS>
        <SMS_MESSAGE>${cdata(sms_mesaj)}</SMS_MESSAGE>
        <NUMBERS>${b.sms_phone}</NUMBERS>
    </SMS>
</CORPORATESMS>`;

return [{ json: { ...b, sms_mesaj, sms_xml } }];

const m = $('Mesajları Hazırla').first().json;
const item = $input.first();
const r = item.json || {};

// Erccell yanıtını oku (binary olarak alınıyor; n8n metin modunda gzip yanıtı çözemiyor)
let yanit = '';
const bin = item.binary && item.binary.data;
if (bin) {
  try {
    if (bin.id || /^filesystem/.test(String(bin.data))) {
      yanit = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
    } else {
      yanit = Buffer.from(bin.data, 'base64').toString('utf8');
    }
  } catch (e) { yanit = ''; }
} else if (typeof r.data === 'string') {
  yanit = r.data;
}
yanit = yanit.trim();

// durum: 'ok' | 'hata' | 'belirsiz' (istek gitti ama yanıt okunamadı)
let durum = 'hata';
let detay = '';
const hataMetni = r.error ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))) : '';

if (!m.sms_phone) {
  detay = 'Geçerli cep telefonu numarası yok (' + m.phone + ')';
} else if (yanit) {
  const sonuc = (yanit.match(/<RESULT>\s*([^<]*?)\s*<\/RESULT>/i) || [])[1];
  if (sonuc !== undefined) {
    // Kısa sayısal kod (örn. 11) hata, uzun değer/ID gönderim kimliği
    durum = !/^-?\d{1,3}$/.test(sonuc) && !/(hata|error|fail|invalid)/i.test(sonuc) ? 'ok' : 'hata';
    detay = 'RESULT=' + sonuc;
  } else {
    detay = yanit.slice(0, 300);
    durum = /(hata|error|fail|invalid|ge[cç]ersiz|yetkisiz|unauthori|denied|ba[sş]ar[iı]s[iı]z)/i.test(yanit) ? 'hata' : 'ok';
  }
} else if (/circular structure/i.test(hataMetni)) {
  // n8n yanıtı çözerken hata verdi; istek Erccell'e ulaştı
  durum = 'belirsiz';
  detay = 'Erccell yanıtı okunamadı';
} else {
  detay = (hataMetni || 'Erccell yanıt vermedi').slice(0, 300);
}
const basarili = durum !== 'hata';

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const telegram_text = [
  '🔔 <b>Yeni Form Başvurusu</b>',
  '',
  '👨‍💼 Atanan: ' + esc(m.sorumlu),
  '📋 Doldurulan form: ' + esc(m.form_adi),
  '🏢 İlgilendiği proje: ' + esc(m.proje),
  '👤 Ad Soyad: ' + esc(m.full_name),
  '📞 Telefon: ' + esc(m.phone),
  '✉️ E-posta: ' + esc(m.email),
  '📝 Cevap: ' + esc(m.cevap),
  '🕒 Tarih: ' + esc(m.tarih),
  '📨 SMS: ' + ({ ok: 'Gönderildi ✅', belirsiz: 'Gönderildi ✅ (yanıt okunamadı)', hata: 'Gönderilemedi ❌' })[durum],
  '🔗 <a href="' + esc(m.bitrix_link) + '">Bitrix\'te aç (#' + esc(m.lead_id) + ')</a>',
].join('\n');

const simdi = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });
const bitrix_yorum = basarili
  ? '✅ SMS GÖNDERİLDİ\nTarih: ' + simdi + '\nNumara: ' + m.phone + '\nMesaj: ' + m.sms_mesaj +
    (durum === 'ok' ? '\nErccell yanıtı: ' + detay : '\nNot: ' + detay)
  : '❌ SMS GÖNDERİLEMEDİ\nTarih: ' + simdi + '\nNumara: ' + m.phone + '\nSebep: ' + detay;

return [{ json: { lead_id: m.lead_id, sms_basarili: basarili, sms_durum: durum, sms_detay: detay, erccell_yanit: yanit, telegram_text, bitrix_yorum } }];
